import java.util.concurrent.*;
class Cinema{boolean[] seats;int sold;Cinema(int n){seats=new boolean[n];}synchronized boolean safe(int s){if(seats[s])return false;seats[s]=true;sold++;return true;}boolean block(int s){synchronized(this){if(seats[s])return false;seats[s]=true;sold++;return true;}}}
public class SeatBooking{static int unsafeOnce()throws Exception{final boolean[]booked={false};final int[]sold={0};CountDownLatch ready=new CountDownLatch(100),go=new CountDownLatch(1);Thread[]t=new Thread[100];for(int i=0;i<100;i++)t[i]=new Thread(()->{ready.countDown();try{go.await();}catch(InterruptedException e){return;}if(!booked[0]){Thread.yield();booked[0]=true;sold[0]++;}});for(Thread q:t)q.start();ready.await();go.countDown();for(Thread q:t)q.join();return sold[0];}
 public static void main(String[]x)throws Exception{for(int i=1;i<=10;i++)System.out.println("Unsafe run "+i+" bookings="+unsafeOnce());Cinema c=new Cinema(10);Thread[]u=new Thread[100];for(int i=0;i<100;i++){final int seat=i%10;u[i]=new Thread(()->c.safe(seat));u[i].start();}for(Thread t:u)t.join();System.out.println("Seats sold: "+c.sold);long st=System.nanoTime();for(int i=0;i<10000;i++)c.safe(i%10);System.out.println("Safe synchronized method elapsed ns="+(System.nanoTime()-st));}}
